<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {RefreshCw} from 'lucide-vue-next'
import {api,cents,type WithdrawalSettings} from '../api/account'
const emit=defineEmits<{notify:[message:string]}>()
const config=ref<WithdrawalSettings|null>(null),fee=ref('10'),loading=ref(false),saving=ref(false),error=ref('')
function apply(c:WithdrawalSettings){config.value={...c};fee.value=(c.fee_bps/100).toFixed(2)}
async function load(){loading.value=true;error.value='';try{apply(await api<WithdrawalSettings>('/admin/withdrawal-settings'))}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function save(){if(!config.value||saving.value)return;saving.value=true;error.value='';try{const next={...config.value,fee_bps:cents(fee.value),rate_yuan:config.value.rate_yuan.trim()};apply(await api<WithdrawalSettings>('/admin/withdrawal-settings','PUT',next));emit('notify','提现手续费与USDT汇率已保存')}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
onMounted(()=>void load())
</script>
<template><section class="withdraw-settings"><header><div><h2>提现设置</h2><p>手续费从申请金额内扣，USDT充值与提现共用汇率。</p></div><button class="secondary-button" :disabled="loading||saving" @click="load"><RefreshCw :size="15"/>重新读取</button></header><p v-if="error" class="form-error" role="alert">{{error}}</p><form v-if="config" class="surface form-stack" @submit.prevent="save"><label>提现手续费（%）<input v-model="fee" required inputmode="decimal" maxlength="6" :disabled="loading||saving"/></label><label>U汇率（1 USDT＝人民币元）<input v-model="config.rate_yuan" required inputmode="decimal" maxlength="24" :disabled="loading||saving"/></label><label class="check"><input v-model="config.usdt_enabled" type="checkbox" :disabled="loading||saving"/>开放USDT提现（TRC20 / ERC20）</label><p class="form-hint">默认10%手续费：申请100元，扣手续费10元，实际到账90元。USDT到账按扣费后金额换算，保留6位小数。</p><p class="form-hint">打码额度＝审核到账的充值＋奖励；打码量为下注金额，撤销不计。未达标禁止新提现，会员可在“用户列表 → 打码设置”调整打码量或开启绿色通道。</p><p class="form-hint">提现审核通过后重新累计。只清除该申请覆盖的记录，审核期间新增的充值、奖励、下注和后台调整保留到下一轮；驳回不重置。多笔申请按已覆盖范围合并处理。</p><p class="form-hint">修改仅影响新申请，已提交的手续费、到账金额、汇率及收款地址保持原快照。修改此处汇率也会更新“收款设置”的USDT汇率。</p><button class="primary-button" :disabled="loading||saving">{{saving?'保存中…':'保存提现设置'}}</button></form></section></template>
<style scoped>.withdraw-settings header{display:flex;justify-content:space-between;gap:16px;margin:24px 0}.withdraw-settings h2{font-size:22px;margin:0 0 8px}.withdraw-settings header p{font-size:13px;color:#93879f}.withdraw-settings form{max-width:800px;padding:26px}.withdraw-settings .check{display:flex;align-items:center;gap:10px}.check input{width:17px;height:17px}.withdraw-settings .form-hint{line-height:1.8}@media(max-width:760px){.withdraw-settings header{align-items:flex-start}.withdraw-settings header p{font-size:11px;line-height:1.8}.withdraw-settings header button{white-space:nowrap}.withdraw-settings form{padding:18px}}</style>
